// El portal manda el lote YA RENDERIZADO (un HTML por persona, con el nombre
// del negocio de cada uno). Acá solo validamos y abrimos un item por
// destinatario: Gmail manda de a uno, nunca BCC a la lista.
// Ojo: el payload del webhook vive en $json.body, no en $json.
const body = $('Webhook').first().json.body ?? {};
const lessonId = body.lesson_id;
const recipients = Array.isArray(body.recipients) ? body.recipients : [];

if (!lessonId) throw new Error('el payload no trae lesson_id');
if (!recipients.length) throw new Error('el payload no trae destinatarios');

return recipients.map((r) => ({
  json: {
    lesson_id: lessonId,
    lesson_title: body.lesson_title ?? '',
    test: body.test === true,
    email: r.email,
    client_name: r.client_name ?? '',
    subject: r.subject,
    html: r.html,
    text: r.text ?? '',
  },
}));
